def announce(function):
    def wrapper():
        return 'start ' + function()
    return wrapper
@announce
def greet(): return 'hello'
print(greet())

from functools import wraps
def label(function):
    @wraps(function)
    def wrapper(*args, **kwargs): return function(*args, **kwargs)
    return wrapper
@label
def add(a, b): return a + b
print(add.__name__, add(2, 3))

def trace(function):
    def wrapper(*args, **kwargs): return function(*args, **kwargs)
    return wrapper
@trace
def multiply(a, b): return a * b
print(multiply(3, 4))

def double_result(function):
    def wrapper(*args, **kwargs): return function(*args, **kwargs) * 2
    return wrapper
@double_result
def value(): return 5
print(value())

def identity_decorator(function):
    return function
@identity_decorator
def ready(): return True
print(callable(ready), ready())
